const body = $('Facts webhook').first().json.body ?? {};
const from = body.from || '2026-10-26', to = body.to || '2026-10-30';
const r4 = (v) => Math.round(v * 10000) / 10000;
const logs = $('Get logs').first().json.logs ?? [];
const total = logs.length, errors = logs.filter((l) => l.status === 'error').length;
const d = logs.map((l) => l.duration_ms).sort((a, b) => a - b);
const p95 = d.length ? d[Math.max(0, Math.ceil(0.95 * d.length) - 1)] : 0;
const groups = {};
for (const l of logs.filter((x) => x.status === 'error')) { const k = l.error_node + '\u0000' + l.error_message; groups[k] = (groups[k] ?? 0) + 1; }
const top = Object.entries(groups).sort((a, b) => b[1] - a[1])[0];
const rel = {};
for (const l of logs.filter((x) => x.route === '자동 답변')) { const x = (rel[l.release] ??= { answers: 0, repeats: 0 }); x.answers += 1; if (l.repeat) x.repeats += 1; }
const rate = (name) => rel[name] ? r4(rel[name].repeats / rel[name].answers) : null;
const alerts = $('Get alerts').first().json.alerts ?? [];
const byReason = {};
for (const a of alerts) byReason[a.reason ?? 'unknown'] = (byReason[a.reason ?? 'unknown'] ?? 0) + 1;
const dlq = $('Get DLQ').first().json.items ?? [];
const q = $('Get quality').first().json.items ?? [];
const quarantine = $('Get quarantine').first().json.size ?? 0;
const usage = $('Get usage').first().json, budget = $('Get budget').first().json;
const users = Object.entries(usage.by_user ?? {}).sort((a, b) => b[1].cost_usd - a[1].cost_usd);
const release = $('Get release').first().json;
const facts = {
  period: { from, to },
  runs: { total, errors, error_rate: total ? r4(errors / total) : 0, p95_ms: p95,
    unanswered_rate: total ? r4(logs.filter((l) => l.route === '담당자 연결').length / total) : 0,
    top_failure: top ? { node: top[0].split('\u0000')[0], message: top[0].split('\u0000')[1], count: top[1] } : null },
  alerts: { count: alerts.length, high: alerts.filter((a) => a.severity === 'high').length, by_reason: byReason },
  dlq: { size: dlq.length, parked: dlq.filter((x) => x.parked).length, waiting: dlq.filter((x) => !x.parked).length },
  quality: { batches: q.length, avg_score: q.length ? r4(q.reduce((s, x) => s + x.score, 0) / q.length) : 0,
    last_score: q.length ? q.at(-1).score : null, rejected_batches: q.filter((x) => x.rejected).length, quarantine },
  cost: { requests: usage.requests ?? 0, calls: usage.calls ?? 0, cost_usd: Math.round((usage.cost_usd ?? 0) * 1e6) / 1e6,
    daily_usd: budget.daily_usd, used_ratio: budget.daily_usd ? r4(budget.used_usd / budget.daily_usd) : 0,
    top_user: users.length ? { user: users[0][0], cost_usd: Math.round(users[0][1].cost_usd * 1e6) / 1e6, share: r4(users[0][1].cost_usd / usage.cost_usd) } : null },
  release: { active: release.active, canary_release: release.canary?.release ?? null, canary_percent: release.canary?.percent ?? 0,
    active_repeat_rate: rate(release.active), canary_repeat_rate: release.canary ? rate(release.canary.release) : null },
};
const s = (red, yellow) => (red ? 'red' : yellow ? 'yellow' : 'green');
const f = facts;
const canaryBad = f.release.canary_release && f.release.canary_repeat_rate !== null && f.release.active_repeat_rate !== null
  && f.release.canary_repeat_rate > 2 * f.release.active_repeat_rate;
const health = {
  runs: s(f.runs.error_rate > 0.01, f.runs.unanswered_rate > 0.02),
  alerts: s(f.alerts.high >= 5, f.alerts.count >= 1),
  dlq: s(f.dlq.parked > 0, f.dlq.size > 0),
  quality: s(f.quality.last_score !== null && f.quality.last_score < 0.8, (f.quality.last_score !== null && f.quality.last_score < 0.9) || f.quality.quarantine > 0),
  cost: s(f.cost.used_ratio >= 1, f.cost.used_ratio >= 0.8),
  release: s(canaryBad, Boolean(f.release.canary_release)),
};
const order = ['runs', 'alerts', 'dlq', 'quality', 'cost', 'release'];
facts.health = health;
facts.red = order.filter((k) => health[k] === 'red');
facts.yellow = order.filter((k) => health[k] === 'yellow');
facts.overall = facts.red.length ? 'red' : facts.yellow.length ? 'yellow' : 'green';
return [{ json: facts }];
